from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(comp)
    template = max(components, key=len)
    minr = min(r for r,c,v in template); maxr = max(r for r,c,v in template)
    minc = min(c for r,c,v in template); maxc = max(c for r,c,v in template)
    ar, ac = (minr+maxr)//2, (minc+maxc)//2
    out = [row[:] for row in grid]
    for comp in components:
        if comp is template or len(comp) != 1:
            continue
        mr, mc, _ = comp[0]
        for r, c, color in template:
            nr, nc = mr + r-ar, mc + c-ac
            if 0 <= nr < h and 0 <= nc < w:
                out[nr][nc] = color
    return out
